sys_script_client.script:
function onSubmit() {

    var maxFileLenth = 44;
    var maxSegmentLenth = 8;
    var regexpSegment = /^[A-Z@#$][a-zA-Z0-9-]{0,7}$/;
    var fileName = g_form.getValue('regexptest');
    var fileNameArray = fileName.split('.');


    //hiding duplicate Messages  
    g_form.hideFieldMsg('regexptest');

    if (fileName > maxFileLenth) {
        g_form.showFieldMsg('regexp', 'Der Dateiname ist zu lang und darf 44 Zeichen nicht überschreiten');
		return false;
    } else {
        for (var i = 0; i < fileNameArray.length; i++) {
            if (fileNameArray[i].length > maxSegmentLenth) {
                g_form.showFieldMsg('regexptest', 'Das Segment ' + (i + 1) + ' ist zu lang! Es hat mehr als 8 Zeichen', 'error');
                return false;
            } else if (!regexpSegment.test(fileNameArray[i])) {
                g_form.showFieldMsg('regexptest', 'Das Segment ' + (i + 1) + ' enthält nicht zulässige Zeichen', 'error');
                return false;
            }
        }
    }
}
